"""Read-only repository verification; temporary side effects, denied network/credentials."""
import os
from pathlib import Path
import runpy
import sys
import tempfile

repo = Path(sys.argv[1]).resolve()
mode = sys.argv[2]
if mode not in ("contracts", "smoke"):
    raise SystemExit("Only contracts or smoke verification is allowed")
essentials = {key: value for key, value in os.environ.items() if key.upper() in {
    "SYSTEMROOT", "WINDIR", "TEMP", "TMP", "PATH", "PATHEXT", "COMSPEC"
}}
os.environ.clear()
os.environ.update(essentials)
os.environ["PYTHON_DOTENV_DISABLED"] = "1"
os.environ["PYTHONIOENCODING"] = "utf-8"
sys.dont_write_bytecode = True
sys.path.insert(0, str(repo))
sys.stdout.reconfigure(encoding="utf-8")
sys.stderr.reconfigure(encoding="utf-8")

with tempfile.TemporaryDirectory(prefix="snipersight-structural-") as scratch:
    safe_root = Path(scratch).resolve()
    os.chdir(safe_root)
    blocked = []

    def contained(path):
        if isinstance(path, int):
            return False
        try:
            return Path(path).resolve().is_relative_to(safe_root)
        except (TypeError, ValueError, OSError):
            return False

    def deny(event):
        blocked.append(event)
        raise PermissionError("isolated verification denied " + event)

    def guard(event, args):
        if event in ("socket.connect", "socket.getaddrinfo", "socket.bind", "subprocess.Popen", "os.system"):
            deny(event)
        if event == "open":
            path, mode, flags = args
            if isinstance(path, (str, bytes, os.PathLike)):
                name = os.path.basename(os.fsdecode(path)).lower()
                if name == ".env" or name.startswith(".env."):
                    deny("credential-file read")
            writing = bool(flags & (os.O_WRONLY | os.O_RDWR | os.O_CREAT | os.O_TRUNC | os.O_APPEND))
            if writing and not contained(path):
                deny("open write outside temporary directory")
        if event == "sqlite3.connect" and not contained(args[0]):
            deny("sqlite outside temporary directory")
        if event in ("os.mkdir", "os.remove", "os.rmdir", "os.chmod", "os.utime", "os.truncate"):
            if not contained(args[0]):
                deny(event + " outside temporary directory")
        if event in ("os.rename", "os.link", "os.symlink"):
            if not contained(args[0]) or not contained(args[1]):
                deny(event + " outside temporary directory")

    sys.addaudithook(guard)
    print("[isolation] dotenv/credentials disabled; network/processes denied; writes confined to temporary directory")
    if mode == "contracts":
        from backend.bot.telemetry.storage import TelemetryStorage
        original_init = TelemetryStorage.__init__
        def isolated_storage_init(self, db_path=None):
            return original_init(self, db_path=str(safe_root / "telemetry.db"))
        TelemetryStorage.__init__ = isolated_storage_init
        print("[isolation] TelemetryStorage db_path redirected to temporary SQLite; real route registration")
        module, command = "backend.diagnostics.capture_contracts", "diff"
    else:
        module, command = "backend.diagnostics.pipeline_smoke", "verify"
    sys.argv = [module, command]
    exit_code = 0
    try:
        runpy.run_module(module, run_name="__main__")
    except SystemExit as exc:
        exit_code = exc.code if isinstance(exc.code, int) else 1
    finally:
        print("[isolation] blocked events:", repr(blocked))
        import logging
        logging.shutdown()
    os.chdir(repo)
raise SystemExit(exit_code)

