def _total_exposure_usd(self) -> float:
        """Estimate total open exposure in USD based on current positions."""
        total = 0.0
        for symbol, qty in self._positions.items():
            if abs(qty) < 1e-9:
                continue
            avg = self._position_avg_price.get(symbol, 0.0)
            total += abs(qty) * avg
        return total

